jobs=[('arsenal_bake',['--script','res://tools/dusk_review/bake_harold_frontage.gd','--','--ground-only']),('arsenal_import',['--headless','--editor','--import']),('after_final',['--script','res://tools/harold_scale_20260915/check.gd','--position','20,30']),('screenshot',['--script','res://tools/harold_scale_20260915/check.gd','--position','20,30','--','--screenshot'])]
